class Solution {
public:
    int findTilt(TreeNode* root) {
        int tilt = 0;
        dfs(root, tilt);
        return tilt;
    }

    int dfs(TreeNode* node, int& tilt) {
        if (!node) return 0;
        int left = dfs(node->left, tilt);
        int right = dfs(node->right, tilt);
        tilt += abs(left - right);
        return node->val + left + right;
    }
};
